math_server = FastMCP("MathServer")


@math_server.tool
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b


@math_server.tool
def subtract(a: float, b: float) -> float:
    """Subtract b from a."""
    return a - b


@math_server.tool
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
    return a * b


@math_server.tool
def divide(a: float, b: float) -> float:
    """Divide a by b."""
    if b == 0:
        raise ValueError("Cannot divide by zero.")
    return a / b


main = FastMCP("MainServer")
main.mount(math_server, namespace="math")

# main now exposes the math server's tools as:
# math_add, math_subtract, math_multiply, math_divide

